<?php $title='Suppliers';require 'includes/header.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['address'])]);flash('success','Supplier added.');redirect('suppliers.php');}$rows=$pdo->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();?><h1>Suppliers</h1><form class="form-card" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="grid"><p><label>Name *</label><input name="name" required></p><p><label>Phone</label><input name="phone"></p><p><label>Email</label><input name="email"></p><p><label>Address</label><input name="address"></p></div><button>Add Supplier</button></form><table><tr><th>Name</th><th>Phone</th><th>Email</th><th>Address</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['email'])?></td><td><?=e($r['address'])?></td></tr><?php endforeach;?></table><?php require 'includes/footer.php';
